{"explanation":"Reconciles each remote event against the persistent local graph. Records are validated for conflicts before any mutation; conflicting events preserve both graph and head. Valid records are merged atomically, then both ancestry walks are performed on the merged graph. Unknown terminal IDs are deduplicated and sorted by Unicode code point order. Classification follows equality, remote advancement, local advancement, fork, or unresolved ancestry, while only advancement changes the local head.","program":"function solve({config,state,event}){
  function own(o,k){return Object.prototype.hasOwnProperty.call(o,k)}
  function cmp(a,b){
    let x=Array.from(a),y=Array.from(b),n=Math.min(x.length,y.length)
    for(let i=0;i<n;i++){let u=x[i].codePointAt(0),v=y[i].codePointAt(0);if(u!==v)return u-v}
    return x.length-y.length
  }
  let s=state||{head:null,records:{}}, r=s.records||{}, add={}, bad=false
  for(let q of event.records){
    let k='\u0000'+q.id, old=own(add,k)?add[k]:own(r,k)?r[k]:null
    if(old!==null&&(old[0]!==q.parent||old[1]!==q.value)){bad=true;break}
    add[k]=[q.parent,q.value]
  }
  function get(g,id){let k='\u0000'+id;return own(g,k)?g[k]:null}
  function walk(h,g){
    let seen={},miss={},x=h
    while(x!==null){
      let rec=get(g,x)
      if(rec===null){miss[x]=1;break}
      if(own(seen,x))break
      seen[x]=1;x=rec[0]
    }
    return {seen:seen,term:x,miss:miss}
  }
  let g=bad?r:Object.assign({},r,add), a=walk(s.head,g), b=walk(event.head,g), mm={}
  for(let x in a.miss)mm[x]=1
  for(let x in b.miss)mm[x]=1
  let missing=Object.keys(mm).sort(cmp)
  if(bad)return {state:s,output:{head:s.head,decision:'conflict',missing:missing}}
  let d,h=s.head
  if(s.head===event.head)d='same'
  else if(s.head===null?b.term===null:own(b.seen,s.head)){d='advance';h=event.head}
  else if(event.head===null?a.term===null:own(a.seen,event.head))d='ahead'
  else if(a.term===null&&b.term===null)d='fork'
  else d='unknown'
  let ns={head:h,records:g}
  return {state:ns,output:{head:h,decision:d,missing:missing}}
}"}
